import { Controller, Get, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLES = ['예산·회계 담당자', '시스템 관리자'];
// 가정: 현재 값이 '사용'/'미사용'이면 여부 설정 항목으로 보고 두 값만 허용한다.
const USE_VALUES = ['사용', '미사용'];
// 가정: 현재 값이 승인번호 부여 방식이면 일·월·연도(프로젝트)·연도(사업장) 중 하나만 허용한다.
const NUMBERING_VALUES = ['일', '월', '연도(프로젝트)', '연도(사업장)'];

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

@Controller('api/v1')
export class FnSfr00207Controller {
  @Get('/config-settings')
  async listConfigSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require(...ROLES);
    const query = checks.queryOf(req.query);
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === '' ? '20' : String(query['size']);
    if (!/^\d+$/.test(pageText)) {
      throw invalid('페이지 번호가 올바르지 않습니다.');
    }
    if (!/^\d+$/.test(sizeText)) {
      throw invalid('페이지 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    const area = query['settingArea'] === undefined || query['settingArea'] === '' ? null : String(query['settingArea']);
    if (area !== null && area.length > 50) {
      throw invalid('설정 영역은 50자 이하로 입력하세요.');
    }
    return transaction(async (db) => {
      const params = { settingArea: area, limit: size, offset: page * size };
      const items = await db.query(
        `SELECT config_setting_id AS "configSettingId",
                setting_area AS "settingArea",
                setting_key AS "settingKey",
                setting_value AS "settingValue",
                applied_from AS "appliedFrom"
           FROM config_setting
          WHERE (CAST(:settingArea AS text) IS NULL OR setting_area = CAST(:settingArea AS text))
          ORDER BY setting_area, setting_key, applied_from DESC
          LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM config_setting
          WHERE (CAST(:settingArea AS text) IS NULL OR setting_area = CAST(:settingArea AS text))`,
        { settingArea: area },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Put('/config-settings/:configSettingId')
  async updateConfigSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(...ROLES);
    const data = checks.inputOf(req.body);
    const id = req.params['configSettingId'];
    if (!/^\d+$/.test(id)) {
      throw invalid('환경설정 ID가 올바르지 않습니다.');
    }
    const settingValue = data['settingValue'];
    if (typeof settingValue !== 'string' || settingValue.trim() === '') {
      throw invalid('설정 값을 입력하세요.');
    }
    if (settingValue.length > 1000) {
      throw invalid('설정 값은 1000자 이하로 입력하세요.');
    }
    const appliedFrom = data['appliedFrom'];
    if (typeof appliedFrom !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(appliedFrom)) {
      throw invalid('적용 시작일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT config_setting_id AS "configSettingId",
                setting_value AS "settingValue"
           FROM config_setting
          WHERE config_setting_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CONFIG_SETTING_NOT_FOUND', '대상 환경설정을 찾을 수 없습니다.');
      }
      const current = String(found[0].settingValue);
      const allowed = USE_VALUES.includes(current)
        ? USE_VALUES
        : NUMBERING_VALUES.includes(current)
          ? NUMBERING_VALUES
          : null;
      if (allowed !== null && !allowed.includes(settingValue)) {
        throw new ApiError(422, 'CONFIG_VALUE_NOT_ALLOWED', '허용되지 않은 설정 값입니다. 허용 값: ' + allowed.join(', '));
      }
      const duplicated = await db.query(
        `SELECT o.config_setting_id
           FROM config_setting c
           JOIN config_setting o
             ON o.setting_area = c.setting_area
            AND o.setting_key = c.setting_key
            AND o.applied_from = CAST(:appliedFrom AS date)
            AND o.config_setting_id <> c.config_setting_id
          WHERE c.config_setting_id = CAST(:id AS bigint)`,
        { id, appliedFrom },
      );
      if (duplicated.length > 0) {
        throw invalid('같은 영역·키에 같은 적용 시작일의 설정이 이미 있습니다.');
      }
      const rows = await db.query(
        `UPDATE config_setting
            SET setting_value = :settingValue,
                applied_from = CAST(:appliedFrom AS date),
                updated_at = now()
          WHERE config_setting_id = CAST(:id AS bigint)
        RETURNING config_setting_id AS "configSettingId",
                  setting_value AS "settingValue"`,
        { id, settingValue, appliedFrom },
      );
      return rows[0];
    });
  }
}

