import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

export default function FnSfr00207Page({ role, notify }: PageProps) {
  const [areaDraft, setAreaDraft] = useState('');
  const [area, setArea] = useState('');
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);
  const [value, setValue] = useState('');
  const [appliedFrom, setAppliedFrom] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/config-settings', role, undefined, { settingArea: area, page, size: SIZE }),
    [role, area, page],
  );

  const open = (row: Row) => {
    setEditing(row);
    setValue(String(row.settingValue ?? ''));
    setAppliedFrom(String(row.appliedFrom ?? '').slice(0, 10));
  };

  const save = async () => {
    if (!editing) {
      return;
    }
    if (value.trim() === '') {
      throw new Error('설정 값을 입력하세요.');
    }
    if (appliedFrom === '') {
      throw new Error('적용 시작일을 입력하세요.');
    }
    await call('PUT', '/config-settings/' + editing.configSettingId, role, {
      settingValue: value,
      appliedFrom,
    });
    notify('환경설정을 변경했습니다.');
    setEditing(null);
    reload();
  };

  const columns: Column[] = [
    { key: 'settingArea', label: '설정 영역' },
    { key: 'settingKey', label: '설정 키' },
    { key: 'settingValue', label: '설정 값' },
    { key: 'appliedFrom', label: '적용 시작일', render: (r) => <DateText value={r.appliedFrom} /> },
    {
      key: 'configSettingId',
      label: '처리',
      render: (r) => (
        <button type="button" onClick={(e) => { e.stopPropagation(); open(r); }}>
          변경
        </button>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>설정 항목</h2>
        <p><Num value={data?.total ?? 0} /></p>
      </section>
      <section className="box span-8">
        <h2>조회 조건</h2>
        <Filters
          onSearch={() => { setPage(0); setArea(areaDraft); }}
          onReset={() => { setAreaDraft(''); setArea(''); setPage(0); }}
        >
          <Field label="설정 영역">
            <TextInput value={areaDraft} onChange={setAreaDraft} />
          </Field>
        </Filters>
      </section>
      <section className="box span-12">
        <h2>환경설정 목록</h2>
        <Band total={data?.total} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable columns={columns} rows={data?.items ?? []} onRowClick={open} empty="환경설정이 없습니다." />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {editing ? (
        <Drawer title="환경설정 변경" onClose={() => setEditing(null)}>
          <Pairs
            items={[
              ['설정 영역', String(editing.settingArea ?? '')],
              ['설정 키', String(editing.settingKey ?? '')],
            ]}
          />
          <Form onSubmit={save} submit="저장" note="변경은 이후 처리되는 업무부터 적용됩니다.">
            <Field label="설정 값" required wide>
              <TextInput value={value} onChange={setValue} />
            </Field>
            <Field label="적용 시작일" required>
              <DateInput value={appliedFrom} onChange={setAppliedFrom} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
